using System.Windows;
using System.Windows.Media;

namespace Arcadia.UI.Media;

/// <summary>
/// Looks up icon geometries generated by tools/Arcadia.IconForge (Themes/Icons.xaml).
/// </summary>
public static class IconCatalog
{
    private static ResourceDictionary? _icons;

    private static ResourceDictionary Icons => _icons ??= new ResourceDictionary
    {
        Source = new Uri("pack://application:,,,/Arcadia.UI;component/Themes/Icons.xaml", UriKind.Absolute),
    };

    public static Geometry? Get(string? name) => string.IsNullOrEmpty(name) ? null : Icons[$"Icon.{name}"] as Geometry;

    public static Geometry? GetAccent(string? name) =>
        string.IsNullOrEmpty(name) ? null : Icons.Contains($"Icon.{name}.Accent") ? Icons[$"Icon.{name}.Accent"] as Geometry : null;
}
